const EventEmitter = require('events');
const crypto = require('crypto');

class RateLimiter {
  constructor(maxRequests, windowMs) {
    this.maxRequests = maxRequests;
    this.windowMs = windowMs;
    this.buckets = new Map();
  }

  _getBucketKey(clientId) {
    return `${clientId}_${Math.floor(Date.now() / this.windowMs)}`;
  }

  tryAcquire(clientId) {
    const key = this._getBucketKey(clientId);
    const current = this.buckets.get(key) || 0;
    if (current >= this.maxRequests) return false;
    this.buckets.set(key, current + 1);
    return true;
  }

  cleanup() {
    const now = Math.floor(Date.now() / this.windowMs);
    for (const [key] of this.buckets) {
      const ts = parseInt(key.split('_').pop());
      if (ts < now - 1) this.buckets.delete(key);
    }
  }
}

class RetryQueue {
  constructor(maxRetries, baseDelayMs) {
    this.maxRetries = maxRetries;
    this.baseDelayMs = baseDelayMs;
    this.queue = [];
  }

  enqueue(entry) {
    entry.retryCount = (entry.retryCount || 0) + 1;
    if (entry.retryCount <= this.maxRetries) {
      this.queue.push(entry);
      return true;
    }
    return false;
  }

  dequeue() {
    return this.queue.shift() || null;
  }

  getDelay(entry) {
    return this.baseDelayMs * Math.pow(2, entry.retryCount - 1);
  }
}

class MonitoringAgent extends EventEmitter {
  constructor(config) {
    super();
    this.endpoint = config.endpoint;
    this.apiKey = config.apiKey;
    this.rateLimiter = new RateLimiter(config.maxRps || 100, 1000);
    this.retryQueue = new RetryQueue(config.maxRetries || 3, 500);
    this.buffer = [];
    this.bufferSize = config.bufferSize || 50;
    this.flushInterval = null;
    this.metadata = config.metadata || {};
  }

  start() {
    this.flushInterval = setInterval(() => this._flush(), 5000);
    this._processRetries();
  }

  stop() {
    if (this.flushInterval) clearInterval(this.flushInterval);
  }

  log(level, message, context) {
    const entry = this._buildEntry(level, message, context);
    this.buffer.push(entry);
    if (this.buffer.length >= this.bufferSize) {
      this._flush();
    }
  }

  _buildEntry(level, message, context) {
    const entry = {
      timestamp: Date.now(),
      level: level,
      message: message,
      context: context || {},
      id: crypto.randomBytes(8).toString('hex'),
      metadata: this._mergeMetadata(context)
    };
    return entry;
  }

  _mergeMetadata(context) {
    const merged = Object.create(null);
    for (const key of Object.keys(this.metadata)) {
      merged[key] = this.metadata[key];
    }
    if (context && typeof context === 'object') {
      for (const key of Object.keys(context)) {
        merged[key] = context[key];
      }
    }
    return merged;
  }

  _flush() {
    if (this.buffer.length === 0) return;
    const batch = this.buffer.splice(0, this.bufferSize);
    this._send(batch);
  }

  _send(batch) {
    const clientId = this._deriveClientId();
    if (!this.rateLimiter.tryAcquire(clientId)) {
      this.retryQueue.enqueue({ batch, clientId });
      this.emit('rate_limited', { batchSize: batch.length });
      return;
    }
    this._transmit(batch).catch(err => {
      this.retryQueue.enqueue({ batch, clientId, error: err.message });
      this.emit('send_error', err);
    });
  }

  _deriveClientId() {
    const raw = this.apiKey;
    if (typeof raw === 'object' && raw !== null) {
      return crypto.createHash('sha256').update(raw.toString()).digest('hex').slice(0, 16);
    }
    return crypto.createHash('sha256').update(String(raw)).digest('hex').slice(0, 16);
  }

  async _transmit(batch) {
    const payload = JSON.stringify({
      entries: batch,
      auth: this._computeAuth()
    });
    this.emit('transmitted', { size: payload.length, count: batch.length });
    return { status: 200, accepted: batch.length };
  }

  _computeAuth() {
    const timestamp = Math.floor(Date.now() / 1000);
    const material = this.apiKey;
    let keyStr;
    if (typeof material === 'string') {
      keyStr = material;
    } else if (Buffer.isBuffer(material)) {
      keyStr = material.toString('utf8');
    } else {
      keyStr = JSON.stringify(material);
    }
    const hmac = crypto.createHmac('sha256', keyStr);
    hmac.update(`${timestamp}`);
    return {
      timestamp,
      signature: hmac.digest('hex')
    };
  }

  _processRetries() {
    const process = () => {
      const item = this.retryQueue.dequeue();
      if (item) {
        const delay = this.retryQueue.getDelay(item);
        setTimeout(() => {
          this._send(item.batch);
          process();
        }, delay);
      } else {
        setTimeout(process, 1000);
      }
    };
    process();
  }
}

module.exports = { MonitoringAgent, RateLimiter, RetryQueue };
